package com.huy.enterprise.inventory; import com.huy.enterprise.common.BaseEntity; import com.huy.enterprise.product.Product; import jakarta.persistence.*; import lombok.*; import java.math.BigDecimal; import java.time.OffsetDateTime; @Getter @Setter @Entity @Table(name="inventory_items",uniqueConstraints=@UniqueConstraint(name="uk_inventory_warehouse_product",columnNames={"warehouse_id","product_id"})) public class InventoryItem extends BaseEntity {@ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="warehouse_id") private Warehouse warehouse; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="product_id") private Product product; @Column(nullable=false,precision=15,scale=2) private BigDecimal quantity=BigDecimal.ZERO; @Column(name="low_stock_threshold",nullable=false,precision=15,scale=2) private BigDecimal lowStockThreshold=BigDecimal.ZERO; @Column(name="last_updated_at",nullable=false) private OffsetDateTime lastUpdatedAt=OffsetDateTime.now();}
